1	/**
2	 * Core shared identifiers and public entity views.
3	 * Source of truth: docs/interfaces/netcode-messages.md and
4	 * docs/components/presentation/DESIGN.md §5 (AnimState),
5	 * docs/interfaces/lobby-and-scores.md (SeatStatus/SeatPublic).
6	 */
7	
8	export type SeatId = 0 | 1 | 2 | 3;
9	
10	export type CharacterId = "gnome" | "sprite" | "halfling" | "dwarf";
11	
12	export type ControlKind = "human" | "ai";
13	
14	export type AnimState =
15	  | "idle"
16	  | "run"
17	  | "jump"
18	  | "duck"
19	  | "throw"
20	  | "drop"
21	  | "push_trip"
22	  | "hurt"
23	  | "stunned"
24	  | "falling";
25	
26	export type SessionPhase =
27	  | "lobby"
28	  | "instructions"
29	  | "level"
30	  | "fork"
31	  | "end_count"
32	  | "end_shares"
33	  | "end_spoils"
34	  | "end_entry"
35	  | "closed";
36	
37	/** A carried treasure reference (first element of a carry stack = top). */
38	export interface CarriedTreasureRef {
39	  instanceId: string;
40	  defId: string;
41	}
42	
43	export interface HaulerPublic {
44	  seatId: number;
45	  character: CharacterId;
46	  control: ControlKind;
47	  x: number;
48	  y: number;
49	  vx: number;
50	  vy: number;
51	  facing: 1 | -1;
52	  anim: AnimState;
53	  carry: CarriedTreasureRef[];
54	  stunned: boolean;
55	  name?: string;
56	}
