  type: "human_takeover";
  seatId: number;
}

export type GameEvent =
  | PickupEvent
  | DropEvent
  | ThrowEvent
  | SpillEvent
  | StunEvent
  | TripEvent
  | TrapTriggerEvent
  | LevelExitEvent
  | SwitchEvent
  | AiTakeoverEvent
  | HumanTakeoverEvent;

