    ...rest,
  };
}

export function resetSeq(): void {
  seqCounter = 0;
}

/** Drive one seat with a tape: one command per tick; returns snapshots. */
export function runTape(
  sim: Simulation,
  seatId: 0 | 1 | 2 | 3,
  tape: InputCommand[],
) {
  const snapshots = [];
  for (const c of tape) {
    sim.applyInput(seatId, c);
    snapshots.push(sim.step().snapshot);
  }
  return snapshots;
}

