toolUseResult.originalFile:
/**
 * C-05 Lobby & Session Service — in-memory session registry + create/join/
 * status behavior (docs/components/lobby-session/DESIGN.md §5–§8,
 * docs/interfaces/lobby-and-scores.md). No DB; process-local maps (MVP).
 *
 * Room spawning is injected (`spawnRoom`) so REST behavior is unit-testable
 * without booting Colyseus. The Colyseus room id doubles as the opaque
 * `sessionId` (contract treats sessionId as opaque; avoids custom-roomId
 * plumbing) — see gameServer.ts.
 */

import type {
  CreateSessionRequest,
  CreateSessionResponse,
  JoinSessionRequest,
  JoinSessionResponse,
  LobbyErrorCode,
  PublicSessionView,
  SeatId,
  SeatStatus,
  SessionPhase,
} from "@dhaul/protocol";
import { JOIN_CODE_ALPHABET, JOIN_CODE_LENGTH } from "@dhaul/protocol";
import { randomInt } from "node:crypto";
import { hashToken, issueToken, verifyToken } from "../session/tokens.js";

export class LobbyError extends Error {
  constructor(
    readonly code: LobbyErrorCode,
    message: string,
  ) {
    super(message);
    this.name = "LobbyError";
  }
}

interface SeatRecord {
  seatId: SeatId;
  occupied: boolean;
  /** Mirrored runtime control for status views; room updates it. */
  control: "human" | "ai" | "empty";
  ready: boolean;
  displayName?: string;
  seatTokenHash?: string;
  reconnectTokenHash?: string;
  connected: boolean;
  disconnectGraceUntil?: number;
}

export interface SessionRecord {
  sessionId: string;
  joinCode: string;
  phase: SessionPhase;
  levelsCompleted: number;
  levelsAfterHoard: number;
  seats: SeatRecord[];
  createdAt: number;
}

export interface LobbyServiceOptions {
  /** Spawn the game room; must return the room id (used as sessionId). */
  spawnRoom: () => Promise<string>;
  /** Public WebSocket endpoint for clients. */
  wsUrl: () => string;
  levelsAfterHoard?: number;
  /** Disconnect grace during which the reconnect token stays valid (ms). */
  reconnectGraceMs?: number;
  now?: () => number;
}

const DISPLAY_NAME_MAX = 16;
const NAME_ALLOWED = /^[A-Za-z0-9 _.'-]+$/;

function normalizeName(raw: unknown): string {
  if (raw === undefined) return "Hauler";
  if (typeof raw !== "string") throw new LobbyError("VALIDATION", "displayName must be a string");
  const name = raw.trim();
  if (name.length === 0) return "Hauler";
  if (name.length > DISPLAY_NAME_MAX || !NAME_ALLOWED.test(name)) {
    throw new LobbyError("VALIDATION", "displayName: 1-16 chars, letters/digits/space/limited punctuation");
  }
  return name;
}

export class LobbyService {
  private readonly sessions = new Map<string, SessionRecord>();
  private readonly byJoinCode = new Map<string, string>();
  private readonly opts: Required<Pick<LobbyServiceOptions, "levelsAfterHoard" | "reconnectGraceMs">> &
    LobbyServiceOptions;

  constructor(options: LobbyServiceOptions) {
    this.opts = {
      levelsAfterHoard: 2,
      reconnectGraceMs: 30_000,
      ...options,
    };
  }

  private now(): number {
    return this.opts.now ? this.opts.now() : Date.now();
  }

  private generateJoinCode(): string {
    for (let attempt = 0; attempt < 100; attempt++) {
      let code = "";
      for (let i = 0; i < JOIN_CODE_LENGTH; i++) {
        code += JOIN_CODE_ALPHABET[randomInt(JOIN_CODE_ALPHABET.length)];
      }
      if (!this.byJoinCode.has(code)) return code;
    }
    throw new LobbyError("INTERNAL", "join code space exhausted");
  }

  async create(body: CreateSessionRequest): Promise<CreateSessionResponse> {
    const displayName = normalizeName(body.displayName);
    const sessionId = await this.opts.spawnRoom();
    const joinCode = this.generateJoinCode();
    const seats: SeatRecord[] = ([0, 1, 2, 3] as const).map((seatId) => ({
      seatId,
      occupied: false,
      control: "empty",
      ready: false,
      connected: false,
    }));
    const session: SessionRecord = {
      sessionId,
      joinCode,
      phase: "level", // P2 slice: rooms boot straight into the box level
      levelsCompleted: 0,
      levelsAfterHoard: this.opts.levelsAfterHoard,
      seats,
      createdAt: this.now(),
    };
    this.sessions.set(sessionId, session);
    this.byJoinCode.set(joinCode, sessionId);

    const { seatToken, reconnectToken } = this.claimSeat(session, 0, displayName);
    return {
      sessionId,
      joinCode,
      wsUrl: this.opts.wsUrl(),
      seats: this.seatStatuses(session),
      hostSeatToken: seatToken,
      reconnectToken,
    };
  }

  join(body: JoinSessionRequest): JoinSessionResponse {
    if (typeof body.joinCode !== "string") {
      throw new LobbyError("VALIDATION", "joinCode required");
    }
    const displayName = normalizeName(body.displayName);
    const code = body.joinCode.trim().toUpperCase();
    const sessionId = this.byJoinCode.get(code);
    const session = sessionId ? this.sessions.get(sessionId) : undefined;
    if (!session) throw new LobbyError("NOT_FOUND", "no session with that code");
    if (session.phase === "closed" || session.phase.startsWith("end_")) {
      throw new LobbyError("CLOSED", "session no longer accepts joiners");
    }
    const seat = session.seats.find((s) => this.seatFree(s));
    if (!seat) throw new LobbyError("FULL", "all four seats are taken");
    const { seatToken, reconnectToken } = this.claimSeat(session, seat.seatId, displayName);
    return {
      sessionId: session.sessionId,
      wsUrl: this.opts.wsUrl(),
      seatId: seat.seatId,
      seatToken,
      reconnectToken,
      seats: this.seatStatuses(session),
      phase: session.phase,
    };
  }

  getPublic(sessionId: string): PublicSessionView {
    const session = this.sessions.get(sessionId);
    if (!session) throw new LobbyError("NOT_FOUND", "unknown session");
    return {
      sessionId: session.sessionId,
      joinCode: session.joinCode,
      phase: session.phase,
      seats: this.seatStatuses(session),
      levelsCompleted: session.levelsCompleted,
      levelsAfterHoard: session.levelsAfterHoard,
    };
  }

  private seatFree(seat: SeatRecord): boolean {
    if (!seat.occupied) return true;
    // Human never connected or disconnected past grace → seat reclaimable.
    if (seat.connected) return false;
    return seat.disconnectGraceUntil !== undefined && this.now() > seat.disconnectGraceUntil;
  }

  private claimSeat(
    session: SessionRecord,
    seatId: SeatId,
    displayName: string,
  ): { seatToken: string; reconnectToken: string } {
    const seat = session.seats[seatId];
    if (!seat) throw new LobbyError("INTERNAL", "bad seat");
    const seatToken = issueToken();
    const reconnectToken = issueToken();
    seat.occupied = true;
    seat.displayName = displayName;
    seat.seatTokenHash = hashToken(seatToken);
    seat.reconnectTokenHash = hashToken(reconnectToken);
    seat.connected = false;
    delete seat.disconnectGraceUntil;
    return { seatToken, reconnectToken };
  }

  seatStatuses(session: SessionRecord): SeatStatus[] {
    return session.seats.map((seat) => {
      const status: SeatStatus = {
        seatId: seat.seatId,
        occupied: seat.occupied,
        control: seat.control,
        ready: seat.ready,
      };
      if (seat.displayName !== undefined) status.displayName = seat.displayName;
      return status;
    });
  }

  // -------------------------------------------------------------------
  // Room-facing API (token verification + runtime mirroring)
  // -------------------------------------------------------------------

  getSession(sessionId: string): SessionRecord | undefined {
    return this.sessions.get(sessionId);
  }

  /** Verify a seat token; returns the bound seatId or null. */
  verifySeatToken(sessionId: string, seatToken: string): SeatId | null {
    const session = this.sessions.get(sessionId);
    if (!session) return null;
    for (const seat of session.seats) {
      if (seat.seatTokenHash && verifyToken(seatToken, seat.seatTokenHash)) {
        return seat.seatId;
      }
    }
    return null;
  }

  /** Reconnect token valid only for its seat and within the grace window. */
  verifyReconnectToken(sessionId: string, seatId: SeatId, token: string): boolean {
    const seat = this.sessions.get(sessionId)?.seats[seatId];
    if (!seat?.reconnectTokenHash) return false;
    if (!verifyToken(token, seat.reconnectTokenHash)) return false;
    if (seat.connected) return true; // rejoin race; token still bound
    if (seat.disconnectGraceUntil === undefined) return true; // never connected yet
    return this.now() <= seat.disconnectGraceUntil;
  }

  markConnected(sessionId: string, seatId: SeatId): void {
    const seat = this.sessions.get(sessionId)?.seats[seatId];
    if (!seat) return;
    seat.connected = true;
    seat.control = "human";
    delete seat.disconnectGraceUntil;
  }

  markDisconnected(sessionId: string, seatId: SeatId, consented: boolean): void {
    const seat = this.sessions.get(sessionId)?.seats[seatId];
    if (!seat) return;
    seat.connected = false;
    seat.control = "ai";
    if (consented) {
      // Intentional leave: free the seat and invalidate credentials.
      seat.occupied = false;
      seat.control = "empty";
      delete seat.seatTokenHash;
      delete seat.reconnectTokenHash;
      delete seat.displayName;
      delete seat.disconnectGraceUntil;
    } else {
      seat.disconnectGraceUntil = this.now() + this.opts.reconnectGraceMs;
    }
  }

  setSeatControl(sessionId: string, seatId: SeatId, control: "human" | "ai"): void {
    const seat = this.sessions.get(sessionId)?.seats[seatId];
    if (seat) seat.control = control;
  }

  markClosed(sessionId: string): void {
    const session = this.sessions.get(sessionId);
    if (session) session.phase = "closed";
  }

  get sessionCount(): number {
    return this.sessions.size;
  }
}

/**
 * HaulSession — Colyseus room hosting the authoritative movement sim (P2).
 *
 * Transport adaptation (see @dhaul/protocol codec.ts module doc): the
 * C2S_Join handshake travels as Colyseus join options; join rejection uses
 * ServerError with COLYSEUS_ERROR_CODES; every other message is sent on a
 * channel named by its wire `type` with the full contract message object as
 * payload. State sync uses plain JSON snapshot broadcasts each tick (no
 * Colyseus schema) — full WorldSnapshot per contract, 4 haulers is tiny.
 */

import { Room, ServerError, type Client } from "@colyseus/core";
import {
  COLYSEUS_ERROR_CODES,
  isC2SInput,
  isJoinOptions,
  protocolVersion,
  type GameEvent,
  type S2C_Error,
  type S2C_Pong,
  type S2C_SeatUpdate,
  type S2C_Snapshot,
  type S2C_Welcome,
  type SeatId,
} from "@dhaul/protocol";
import { getLevel, P2_LEVEL_ID } from "../content.js";
import type { LobbyService } from "../lobby/service.js";
import { DEFAULT_SIM_CONFIG } from "../sim/config.js";
import { Simulation } from "../sim/simulation.js";

/** Injected process-wide deps (rooms are constructed by Colyseus). */
interface RoomDeps {
  lobby: LobbyService;
}

let deps: RoomDeps | undefined;

export function setHaulSessionDeps(d: RoomDeps): void {
  deps = d;
}

interface ClientMeta {
  seatId: SeatId;
  /** Token bucket for input rate limiting (~tickRate * 2). */
  tokens: number;
  lastRefillMs: number;
}

const TICK_MS = 1000 / DEFAULT_SIM_CONFIG.tickRate;
const INPUT_RATE_LIMIT_PER_SEC = DEFAULT_SIM_CONFIG.tickRate * 2;
const TICK_LAG_LOG_EVERY = 150; // ~5s at 30 Hz

export class HaulSession extends Room {
  private sim!: Simulation;
  private startedAtMs = 0;
  private readonly meta = new Map<string, ClientMeta>();

  private get lobby(): LobbyService {
    if (!deps) throw new Error("HaulSession deps not initialised");
    return deps.lobby;
  }

  override onCreate(): void {
    this.maxClients = 4;
    this.autoDispose = false; // lobby owns lifecycle (created before first WS join)
    this.sim = new Simulation(getLevel(P2_LEVEL_ID), DEFAULT_SIM_CONFIG);
    this.startedAtMs = Date.now();

    this.onMessage("input", (client, payload: unknown) => this.handleInput(client, payload));
    this.onMessage("ping", (client, payload: unknown) => {
      const clientTime =
        typeof payload === "object" && payload !== null
          ? Number((payload as { clientTime?: unknown }).clientTime ?? 0)
          : 0;
      const pong: S2C_Pong = { type: "pong", clientTime, serverTime: Date.now() };
      client.send("pong", pong);
    });
    this.onMessage("leave", (client) => {
      client.leave(1000); // consented
    });
    // Forward-compatibility: ignore unknown channels silently.
    this.onMessage("*", () => undefined);

    this.setSimulationInterval(() => this.tick(), TICK_MS);
  }

  /** roomId doubles as the contract sessionId (see lobby service). */
  private get sessionId(): string {
    return this.roomId;
  }

  override onJoin(client: Client, options: unknown): void {
    if (!isJoinOptions(options)) {
      throw new ServerError(COLYSEUS_ERROR_CODES.PROTOCOL, "malformed join options");
    }
    if (options.protocolVersion !== protocolVersion) {
      throw new ServerError(
        COLYSEUS_ERROR_CODES.PROTOCOL,
        `protocol mismatch: server=${protocolVersion} client=${options.protocolVersion}`,
      );
    }
    if (options.sessionId !== this.sessionId) {
      throw new ServerError(COLYSEUS_ERROR_CODES.AUTH, "wrong session");
    }
    const seatId = this.lobby.verifySeatToken(this.sessionId, options.seatToken);
    if (seatId === null) {
      throw new ServerError(COLYSEUS_ERROR_CODES.AUTH, "invalid seat token");
    }
    if (
      options.reconnectToken !== undefined &&
      !this.lobby.verifyReconnectToken(this.sessionId, seatId, options.reconnectToken)
    ) {
      throw new ServerError(COLYSEUS_ERROR_CODES.AUTH, "reconnect grace expired");
    }
    // One live connection per seat: a fresh valid join replaces a stale one.
    for (const [sid, m] of this.meta) {
      if (m.seatId === seatId && sid !== client.sessionId) {
        this.clients.find((c) => c.sessionId === sid)?.leave(1000);
        this.meta.delete(sid);
      }
    }

    this.meta.set(client.sessionId, {
      seatId,
      tokens: INPUT_RATE_LIMIT_PER_SEC,
      lastRefillMs: Date.now(),
    });
    const session = this.lobby.getSession(this.sessionId);
    const displayName = session?.seats[seatId]?.displayName;
    const events = this.sim.bindHuman(seatId, client.sessionId, displayName);
    this.lobby.markConnected(this.sessionId, seatId);

    const welcome: S2C_Welcome = {
      type: "welcome",
      protocolVersion,
      sessionId: this.sessionId,
      seatId,
      reconnectToken: options.reconnectToken ?? "", // rotated only by lobby (MVP: unchanged)
      rngSeed: this.sim.config.rngSeed,
      rulesetVersion: this.sim.config.rulesetVersion,
      tickRate: 30,
      phase: "level",
      snapshot: this.sim.buildSnapshot(),
    };
    client.send("welcome", welcome);
    this.broadcastEvents(events);
    this.broadcastSeatUpdate();
  }

  override onLeave(client: Client, consented?: boolean): void {
    const m = this.meta.get(client.sessionId);
    this.meta.delete(client.sessionId);
    if (!m) return;
    // Another live connection already owns the seat (reconnect race) → no-op.
    for (const other of this.meta.values()) {
      if (other.seatId === m.seatId) return;
    }
    const events = this.sim.releaseHuman(m.seatId, consented === true);
    this.lobby.markDisconnected(this.sessionId, m.seatId, consented === true);
    this.broadcastEvents(events);
    this.broadcastSeatUpdate();
  }

  override onDispose(): void {
    this.lobby.markClosed(this.sessionId);
  }

  private handleInput(client: Client, payload: unknown): void {
    const m = this.meta.get(client.sessionId);
    if (!m) return;
    if (!isC2SInput(payload)) return; // drop malformed silently (untrusted)
    if (payload.seatId !== m.seatId) {
      const err: S2C_Error = {
        type: "error",
        code: "AUTH",
        message: "seatId does not match seat token",
      };
      client.send("error", err);
      return;
    }
    // Token-bucket rate limit (input-commands.md: rate limit > tickRate * 2).
    const now = Date.now();
    m.tokens = Math.min(
      INPUT_RATE_LIMIT_PER_SEC,
      m.tokens + ((now - m.lastRefillMs) / 1000) * INPUT_RATE_LIMIT_PER_SEC,
    );
    m.lastRefillMs = now;
    if (m.tokens < 1) return; // drop excess silently
    m.tokens -= 1;

    this.sim.applyInput(m.seatId, payload.command);
  }

  private tick(): void {
    const { snapshot, events } = this.sim.step();
    const msg: S2C_Snapshot = { type: "snapshot", snapshot };
    this.broadcast("snapshot", msg);
    if (events.length > 0) {
      this.broadcastEvents(events);
      this.broadcastSeatUpdate();
    }
    // Tick lag metric (Implementation Plan P2 exit criterion).
    if (snapshot.tick % TICK_LAG_LOG_EVERY === 0) {
      const expectedMs = this.startedAtMs + snapshot.tick * TICK_MS;
      const lagMs = Math.round(Date.now() - expectedMs);
      console.log(
        `[haul_session ${this.sessionId}] tick=${snapshot.tick} lagMs=${lagMs} clients=${this.clients.length}`,
      );
    }
  }

  private broadcastEvents(events: GameEvent[]): void {
    for (const event of events) {
      if (event.type === "ai_takeover" || event.type === "human_takeover") {
        this.lobby.setSeatControl(
          this.sessionId,
          event.seatId as SeatId,
          event.type === "ai_takeover" ? "ai" : "human",
        );
      }
      this.broadcast("event", { type: "event", event });
    }
  }

  private broadcastSeatUpdate(): void {
    const msg: S2C_SeatUpdate = { type: "seat_update", seats: this.sim.seatsPublic() };
    this.broadcast("seat_update", msg);
  }
}

