/**
 * P2 dev render scene: draws the box level's solid grid + 4 haulers as
 * colored placeholder rects (own hauler predicted, remotes interpolated).
 * Not the real C-02 presentation — placeholders per Implementation Plan P2.
 */

import Phaser from "phaser";
import type { SessionClient } from "../net/sessionClient.js";
import type { LevelGeometry } from "../net/lobbyClient.js";

const SEAT_COLORS = [0xff5555, 0x55aaff, 0x55dd55, 0xffcc44];

export class GameScene extends Phaser.Scene {
  private session!: SessionClient;
  private geometry!: LevelGeometry;
  private gfx!: Phaser.GameObjects.Graphics;
  private labels: Phaser.GameObjects.Text[] = [];
  private hud!: Phaser.GameObjects.Text;

  constructor() {
    super("Game");
  }

  init(data: { session: SessionClient; geometry: LevelGeometry }): void {
    this.session = data.session;
    this.geometry = data.geometry;
  }

  create(): void {
    this.cameras.main.setBackgroundColor("#12101c");
    this.drawStatic();
    this.gfx = this.add.graphics();
    for (let i = 0; i < 4; i++) {
      this.labels.push(
        this.add.text(0, 0, "", { fontSize: "10px", color: "#ffffff" }).setDepth(10),
      );
    }
    this.hud = this.add
      .text(8, 8, "", { fontSize: "12px", color: "#9fe" })
      .setScrollFactor(0)
      .setDepth(20);
  }

  private drawStatic(): void {
    const bs = this.geometry.blockSizePx;
    const g = this.add.graphics();
    g.fillStyle(0x2a2740, 1);
    for (let cy = 0; cy < this.geometry.height; cy++) {
      const row = this.geometry.solid[cy] ?? "";
      for (let cx = 0; cx < this.geometry.width; cx++) {
        if (row[cx] === "#") g.fillRect(cx * bs, cy * bs, bs - 1, bs - 1);
      }
    }
    const e = this.geometry.exit;
    g.fillStyle(0x3a6, 0.5);
    g.fillRect(e.x, e.y, e.width, e.height);
  }

  override update(): void {
    if (!this.gfx) return;
    this.gfx.clear();
    const kin = { halfW: 12, halfH: 14 };
    const now = performance.now();
    const snap = this.session.latestSnapshot();
    const local = this.session.localState();
    const localSeat = this.session.seatId;

    for (let seatId = 0; seatId < 4; seatId++) {
      let x: number | null = null;
      let y: number | null = null;
      let facing = 1;
      let tag = "";
      if (seatId === localSeat && local) {
        x = local.x;
        y = local.y;
        facing = local.facing;
        tag = "you";
      } else {
        const s = this.session.interpolator().sample(seatId, now);
        if (s) {
          x = s.x;
          y = s.y;
          facing = s.facing;
          tag = s.control === "ai" ? "ai" : (s.name ?? "human");
        }
      }
      const label = this.labels[seatId]!;
      if (x === null || y === null) {
        label.setText("");
        continue;
      }
      const color = SEAT_COLORS[seatId]!;
      this.gfx.fillStyle(color, 1);
      this.gfx.fillRect(x - kin.halfW, y - kin.halfH, kin.halfW * 2, kin.halfH * 2);
      // facing pip
      this.gfx.fillStyle(0xffffff, 1);
      this.gfx.fillRect(x + facing * (kin.halfW - 4) - 2, y - 4, 4, 4);
      label.setText(tag).setPosition(x - kin.halfW, y - kin.halfH - 12);
    }

    const cstate = this.session.connectionState;
    this.hud.setText(
      `seat ${localSeat}  ${cstate}  tick ${snap?.tick ?? "-"}  ack ${
        snap ? (snap.lastProcessedInputSeq[localSeat] ?? 0) : "-"
      }`,
    );
  }
}

/**
 * P2 lobby-less dev UI (DOM): create / join-by-code, then hand tokens to the
 * SessionClient and start the render scene. Real lobby UX is C-01 (P4).
 */

import type Phaser from "phaser";
import { createSession, fetchLevel, joinSession } from "./net/lobbyClient.js";
import { SessionClient } from "./net/sessionClient.js";
import { loadBundle, type SessionBundle } from "./net/tokenStore.js";
import { GameScene } from "./scenes/GameScene.js";

const SERVER_URL = import.meta.env["VITE_SERVER_URL"] ?? "http://localhost:8080";
const P2_LEVEL_ID = "box_level";

export function mountDevLobby(game: Phaser.Game): void {
  const root = document.createElement("div");
  root.style.cssText =
    "position:fixed;inset:0;display:flex;align-items:center;justify-content:center;font-family:system-ui;background:#000c;z-index:100;color:#eee";
  root.innerHTML = `
    <div style="background:#1a1626;padding:24px;border-radius:8px;min-width:320px">
      <h2 style="margin:0 0 12px">Dungeon Haul — P2 dev</h2>
      <input id="dh-name" placeholder="Name" value="Hauler" style="width:100%;margin-bottom:8px;padding:6px" />
      <button id="dh-create" style="width:100%;padding:8px;margin-bottom:12px">Create room</button>
      <div style="display:flex;gap:8px">
        <input id="dh-code" placeholder="JOIN CODE" style="flex:1;padding:6px;text-transform:uppercase" />
        <button id="dh-join" style="padding:8px">Join</button>
      </div>
      <p id="dh-status" style="margin:12px 0 0;color:#9fe;min-height:1.2em"></p>
    </div>`;
  document.body.appendChild(root);

  const status = root.querySelector<HTMLParagraphElement>("#dh-status")!;
  const nameInput = root.querySelector<HTMLInputElement>("#dh-name")!;
  const setStatus = (s: string): void => {
    status.textContent = s;
  };

  const start = async (bundle: SessionBundle, resume: boolean): Promise<void> => {
    const geometry = await fetchLevel(bundle.serverUrl, P2_LEVEL_ID);
    const session = new SessionClient(geometry, {
      onState: (st, detail) => setStatus(`${st}${detail ? " — " + detail : ""}`),
    });
    if (resume) {
      const ok = await session.tryResume();
      if (!ok) {
        setStatus("could not resume; create or join again");
        return;
      }
    } else {
      await session.connect(bundle);
    }
    root.remove();
    if (!game.scene.getScene("Game")) game.scene.add("Game", GameScene, false);
    game.scene.start("Game", { session, geometry });
  };

  root.querySelector<HTMLButtonElement>("#dh-create")!.onclick = async () => {
    try {
      setStatus("creating…");
      const res = await createSession(SERVER_URL, nameInput.value.trim() || "Hauler");
      setStatus(`room ${res.joinCode} — share it with players`);
      await start(
        {
          serverUrl: SERVER_URL,
          wsUrl: res.wsUrl,
          sessionId: res.sessionId,
          seatId: 0,
          seatToken: res.hostSeatToken,
          reconnectToken: res.reconnectToken,
          displayName: nameInput.value.trim() || "Hauler",
        },
        false,
      );
    } catch (e) {
      setStatus(`error: ${(e as Error).message}`);
    }
  };

  root.querySelector<HTMLButtonElement>("#dh-join")!.onclick = async () => {
    try {
      const code = root.querySelector<HTMLInputElement>("#dh-code")!.value.trim();
      setStatus("joining…");
      const res = await joinSession(SERVER_URL, code, nameInput.value.trim() || "Hauler");
      await start(
        {
          serverUrl: SERVER_URL,
          wsUrl: res.wsUrl,
          sessionId: res.sessionId,
          seatId: res.seatId,
          seatToken: res.seatToken,
          reconnectToken: res.reconnectToken,
          displayName: nameInput.value.trim() || "Hauler",
        },
        false,
      );
    } catch (e) {
      setStatus(`error: ${(e as Error).message}`);
    }
  };

  // Auto-resume on refresh if a session bundle is present.
  const existing = loadBundle();
  if (existing) {
    setStatus("resuming previous session…");
    void start(existing, true).catch(() => setStatus("resume failed; create or join"));
  }
}

import Phaser from "phaser";
import { BootScene } from "./scenes/BootScene";
import { mountDevLobby } from "./devLobby";

/** Frozen logical resolution: 960×540, integer-friendly FIT + letterbox. */
export const LOGICAL_WIDTH = 960;
export const LOGICAL_HEIGHT = 540;

const game = new Phaser.Game({
  type: Phaser.AUTO,
  parent: "game",
  width: LOGICAL_WIDTH,
  height: LOGICAL_HEIGHT,
  backgroundColor: "#1a1626",
  scale: {
    mode: Phaser.Scale.FIT,
    autoCenter: Phaser.Scale.CENTER_BOTH,
  },
  scene: [BootScene],
});

// P2: DOM create/join UI overlays the canvas; on connect it starts GameScene.
mountDevLobby(game);

