import Phaser from "phaser";
import { BootScene } from "./scenes/BootScene";
import { mountDevLobby } from "./devLobby";

/** Frozen logical resolution: 960×540, integer-friendly FIT + letterbox. */
export const LOGICAL_WIDTH = 960;
export const LOGICAL_HEIGHT = 540;

const game = new Phaser.Game({
  type: Phaser.AUTO,
  parent: "game",
  width: LOGICAL_WIDTH,
  height: LOGICAL_HEIGHT,
  backgroundColor: "#1a1626",
  scale: {
    mode: Phaser.Scale.FIT,
    autoCenter: Phaser.Scale.CENTER_BOTH,
  },
  scene: [BootScene],
});

// P2: DOM create/join UI overlays the canvas; on connect it starts GameScene.
mountDevLobby(game);

import { fileURLToPath } from "node:url";
import { defineConfig } from "vitest/config";

// Resolve @dhaul/protocol from source so client net unit tests run without a
// prior workspace build. Pure net modules (prediction/interp/mapper) don't
// import Phaser, so they run in a node environment.
export default defineConfig({
  resolve: {
    alias: {
      "@dhaul/protocol": fileURLToPath(
        new URL("../packages/protocol/src/index.ts", import.meta.url),
      ),
    },
  },
  test: {
    environment: "node",
    include: ["test/**/*.test.ts"],
  },
});

import { describe, expect, it } from "vitest";
import type { InputCommand, WorldSnapshot } from "@dhaul/protocol";
import { LocalPredictor } from "../src/net/prediction.js";
import {
  createBody,
  DEFAULT_KINEMATICS,
  stepHauler,
  type SolidGrid,
} from "../src/net/kinematics.js";

// Same enclosed box as the server fixture: 21x6, floor row 5, walls col 0/20.
const GRID: SolidGrid = {
  blockSizePx: 32,
  widthCells: 21,
  heightCells: 6,
  isSolid: (cx, cy) =>
    cx < 0 || cy < 0 || cx >= 21 || cy >= 6 || cy === 5 || cx === 0 || cx === 20,
};

const cmd = (seq: number, x: -1 | 0 | 1, jump = false): InputCommand => ({
  seq,
  axes: { x, y: 0 },
  jump,
  action: false,
  start: false,
});

function snapshotFromBody(seq: number, x: number, y: number, vx: number, vy: number): WorldSnapshot {
  return {
    tick: seq,
    phase: "level",
    levelId: "box_level",
    levelsCompleted: 0,
    levelsAfterHoard: 2,
    lastProcessedInputSeq: { 0: seq },
    haulers: [
      {
        seatId: 0,
        character: "gnome",
        control: "human",
        x,
        y,
        vx,
        vy,
        facing: 1,
        anim: vy < 0 ? "jump" : "idle",
        carry: [],
        stunned: false,
      },
    ],
    treasures: [],
    traps: [],
    switches: [],
  };
}

describe("LocalPredictor: parity with server kinematics", () => {
  it("predicts the same path the server sim produces for identical inputs", () => {
    const spawn = { x: 2 * 32 + 16, y: 4 * 32 + 16 };
    const predictor = new LocalPredictor(GRID, DEFAULT_KINEMATICS, 0);
    // Seed the predictor at spawn via a reconcile from an initial snapshot.
    predictor.reconcile(snapshotFromBody(0, spawn.x, spawn.y, 0, 0));

    const authBody = createBody(spawn.x, spawn.y);
    const tape = [
      ...Array.from({ length: 8 }, (_, i) => cmd(i + 1, 1)),
      ...Array.from({ length: 6 }, (_, i) => cmd(i + 9, 1, true)),
    ];
    for (const c of tape) {
      predictor.predict(c);
      stepHauler(authBody, { moveX: c.axes.x, jump: c.jump }, GRID, DEFAULT_KINEMATICS);
    }
    // Unreconciled prediction equals a raw server-side sim of the same tape.
    expect(predictor.state.x).toBeCloseTo(authBody.x, 5);
    expect(predictor.state.y).toBeCloseTo(authBody.y, 5);
  });
});

describe("LocalPredictor: reconciliation", () => {
  it("drops acked inputs and replays the unacked remainder", () => {
    const spawn = { x: 100, y: 144 };
    const predictor = new LocalPredictor(GRID, DEFAULT_KINEMATICS, 0);
    predictor.reconcile(snapshotFromBody(0, spawn.x, spawn.y, 0, 0));

    for (let i = 1; i <= 10; i++) predictor.predict(cmd(i, 1));
    expect(predictor.pendingCount).toBe(10);

    // Server acked through seq 6 at an authoritative position.
    predictor.reconcile(snapshotFromBody(6, 130, spawn.y, 40, 0));
    expect(predictor.pendingCount).toBe(4); // seqs 7..10 replayed

    // Result is server pos advanced by 4 more right-moving steps (x increased).
    expect(predictor.state.x).toBeGreaterThan(130);
  });

  it("hard-corrects toward server position on large divergence", () => {
    const predictor = new LocalPredictor(GRID, DEFAULT_KINEMATICS, 0);
    predictor.reconcile(snapshotFromBody(0, 100, 144, 0, 0));
    for (let i = 1; i <= 5; i++) predictor.predict(cmd(i, 1));
    const before = predictor.state.x;
    // Server says we were actually shoved far left, all inputs acked.
    predictor.reconcile(snapshotFromBody(5, 50, 144, 0, 0));
    expect(predictor.state.x).toBe(50);
    expect(predictor.state.x).toBeLessThan(before);
  });
});

import { describe, expect, it } from "vitest";
import type { HaulerPublic, WorldSnapshot } from "@dhaul/protocol";
import { RemoteInterpolator } from "../src/net/interpolation.js";

function snap(tick: number, seat1X: number): WorldSnapshot {
  const h: HaulerPublic = {
    seatId: 1,
    character: "sprite",
    control: "human",
    x: seat1X,
    y: 100,
    vx: 0,
    vy: 0,
    facing: 1,
    anim: "run",
    carry: [],
    stunned: false,
    name: "Bea",
  };
  return {
    tick,
    phase: "level",
    levelsCompleted: 0,
    levelsAfterHoard: 2,
    lastProcessedInputSeq: {},
    haulers: [h],
    treasures: [],
    traps: [],
    switches: [],
  };
}

describe("RemoteInterpolator", () => {
  it("interpolates between two snapshots at the delayed render time", () => {
    const interp = new RemoteInterpolator(66);
    interp.push(snap(1, 0), 1000);
    interp.push(snap(2, 100), 1100);
    // Render time = now - 66. At now=1132, target=1066 → 66% between 1000/1100.
    const s = interp.sample(1, 1132);
    expect(s).not.toBeNull();
    expect(s!.x).toBeCloseTo(66, 0);
    expect(s!.name).toBe("Bea");
  });

  it("excludes the local seat and returns null for unseen seats", () => {
    const interp = new RemoteInterpolator();
    interp.push(snap(1, 10), 1000, /* excludeSeatId */ 1);
    expect(interp.sample(1, 1100)).toBeNull();
    expect(interp.sample(3, 1100)).toBeNull();
  });

  it("holds the last transform on buffer underrun (no long extrapolation)", () => {
    const interp = new RemoteInterpolator(66);
    interp.push(snap(1, 0), 1000);
    interp.push(snap(2, 100), 1100);
    // Far future: render time past newest sample → hold newest, don't extrapolate.
    const s = interp.sample(1, 5000);
    expect(s!.x).toBe(100);
  });
});

import { beforeEach, describe, expect, it, vi } from "vitest";
import { KeyboardInputMapper } from "../src/net/inputMapper.js";

class FakeWindow {
  private handlers = new Map<string, ((e: unknown) => void)[]>();
  addEventListener(type: string, fn: (e: unknown) => void): void {
    const arr = this.handlers.get(type) ?? [];
    arr.push(fn);
    this.handlers.set(type, arr);
  }
  fire(type: string, e: unknown): void {
    for (const fn of this.handlers.get(type) ?? []) fn(e);
  }
}

let win: FakeWindow;
let mapper: KeyboardInputMapper;

beforeEach(() => {
  win = new FakeWindow();
  mapper = new KeyboardInputMapper();
  mapper.attach(win as unknown as Window);
});

describe("KeyboardInputMapper", () => {
  it("maps arrows/Z/X into a normalized InputCommand with monotonic seq", () => {
    win.fire("keydown", { code: "ArrowRight" });
    win.fire("keydown", { code: "KeyZ" });
    const c1 = mapper.sample();
    expect(c1).toMatchObject({ seq: 1, axes: { x: 1, y: 0 }, jump: true, action: false });
    win.fire("keyup", { code: "ArrowRight" });
    win.fire("keydown", { code: "KeyX" });
    const c2 = mapper.sample();
    expect(c2).toMatchObject({ seq: 2, axes: { x: 0 }, action: true });
  });

  it("cancels opposing axis keys to 0", () => {
    win.fire("keydown", { code: "ArrowLeft" });
    win.fire("keydown", { code: "ArrowRight" });
    expect(mapper.sample().axes.x).toBe(0);
  });

  it("resetSeq restarts the sequence (reused on re-welcome)", () => {
    mapper.sample();
    mapper.sample();
    mapper.resetSeq();
    expect(mapper.sample().seq).toBe(1);
  });

  it("blur clears held keys", () => {
    win.fire("keydown", { code: "ArrowLeft" });
    win.fire("blur", {});
    expect(mapper.sample().axes.x).toBe(0);
  });
});

describe("hidden-vitest-mock guard", () => {
  it("vi is available", () => {
    expect(vi).toBeTruthy();
  });
});

