import { startGameServer } from '/Users/atarzwell/src/dhaul4/server/dist/gameServer.js';
import { Client } from '@colyseus/sdk';

const s = await startGameServer({ port: 0, wsPort: 0 });

// Health
const health = await fetch(`${s.httpUrl}/health`).then(r => r.json());
console.log('HEALTH', JSON.stringify(health));

// Create + join REST
const created = await fetch(`${s.httpUrl}/api/v1/sessions`, {method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({displayName:'Alice'})}).then(r=>r.json());
console.log('CREATE joinCode', created.joinCode, 'session', created.sessionId);
const joined = await fetch(`${s.httpUrl}/api/v1/sessions/join`, {method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({joinCode:created.joinCode,displayName:'Bob'})}).then(r=>r.json());
console.log('JOIN seatId', joined.seatId);

function connect(bundle, reconnect=false){
  const c = new Client(s.wsUrl);
  return c.joinById(bundle.sessionId, { protocolVersion:1, sessionId:bundle.sessionId, seatToken:bundle.token, ...(reconnect?{reconnectToken:bundle.rc}:{}) });
}
const r0 = await connect({sessionId:created.sessionId, token:created.hostSeatToken});
const r1 = await connect({sessionId:created.sessionId, token:joined.seatToken});
let snap0, snap1;
r0.onMessage('snapshot', m => snap0 = m.snapshot);
r1.onMessage('snapshot', m => snap1 = m.snapshot);
r0.onMessage('welcome', ()=>{});
r1.onMessage('welcome', ()=>{});
r0.onMessage('*',()=>{}); r1.onMessage('*',()=>{});

// seat0 runs right, seat1 runs left for 1s
let seq0=0, seq1=0;
const iv = setInterval(()=>{
  r0.send('input',{type:'input',seatId:0,command:{seq:++seq0,axes:{x:1,y:0},jump:false,action:false,start:false}});
  r1.send('input',{type:'input',seatId:1,command:{seq:++seq1,axes:{x:-1,y:0},jump:false,action:false,start:false}});
}, 33);
await new Promise(r=>setTimeout(r,1200));
clearInterval(iv);
const h0 = snap0.haulers.find(h=>h.seatId===0);
const h1 = snap0.haulers.find(h=>h.seatId===1);
console.log('SEAT0 x=', h0.x.toFixed(1), 'control', h0.control, 'ack', snap0.lastProcessedInputSeq[0]);
console.log('SEAT1 x=', h1.x.toFixed(1), 'control', h1.control, 'ack', snap0.lastProcessedInputSeq[1]);
console.log('MOVED_APART', (h0.x > 96 && h1.x < h1.x + 999) ? 'yes' : 'no', 'seat0>spawn', h0.x > 2*32+16, 'seat1<spawn', h1.x < 4*32+16);
console.log('BOTH_HUMAN', h0.control==='human' && h1.control==='human');
await r0.leave(true); await r1.leave(true);
await s.shutdown();
process.exit(0);
EOF
